    @EventHandler( payloadType=UpdateRegulationEvent.class )
    public void handle( UpdateRegulationEvent event) {
    	LOGGER.info("handling UpdateRegulationEvent - " + event );
    	
	    Regulation entity = new Regulation();
            entity.setRegulationId( event.getRegulationId() );
            entity.setName( event.getName() );
            entity.setCitation( event.getCitation() );
            entity.setJurisdiction( event.getJurisdiction() );
            entity.setPublicationUrl( event.getPublicationUrl() );
            entity.setObligations( event.getObligations() );
            entity.setCompliancePrograms( event.getCompliancePrograms() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindRegulation( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllRegulation( entity );        
    }
    
