    /**
     * Method to retrieve the Regulation via an RegulationPrimaryKey.
     * @param 	id Long
     * @return 	Regulation
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Regulation handle( FindRegulationQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getRegulationId() );
    }
    
    /**
     * Method to retrieve a collection of all Regulations
     *
     * @param	query	FindAllRegulationQuery 
     * @return 	List<Regulation> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Regulation> handle( FindAllRegulationQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindRegulation,
 * but only if the id matches
 *
 * @param		entity	Regulation
 */
	protected void emitFindRegulation( Regulation entity ) {
		LOGGER.info("handling emitFindRegulation" );
		
	    queryUpdateEmitter.emit(FindRegulationQuery.class,
	                            query -> query.getFilter().getRegulationId().equals(entity.getRegulationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllRegulation
	 * 
	 * @param		entity	Regulation
	 */
	protected void emitFindAllRegulation( Regulation entity ) {
		LOGGER.info("handling emitFindAllRegulation" );
		
	    queryUpdateEmitter.emit(FindAllRegulationQuery.class,
	                            query -> true,
	                            entity);
	}

